contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Deposit amount into c, attempt withdrawAll; if the first withdrawAll does not revert,
    // then c's balance must drop by at least the deposit amount, and a second withdrawAll
    // (attempted after the first) must not succeed in transferring additional ETH to this contract.
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // deposit into c
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // record contract balance before first withdraw
        uint beforeBalance = address(c).balance;

        // try first withdrawAll and capture whether it reverted
        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint afterFirst = address(c).balance;

        // Now attempt a second withdrawAll and detect whether it transfers funds (i.e., succeeds)
        // We measure success by whether the call did not revert and caused c's balance to decrease further.
        bool secondReverted;
        uint beforeSecond = address(c).balance;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }
        uint afterSecond = address(c).balance;

        // General rule: either the first withdraw reverted, or (1) the first withdraw reduced c's balance by at least depositAmount,
        // and (2) the second withdraw did not succeed in reducing c's balance further (i.e., either it reverted or afterSecond == afterFirst).
        assert(firstReverted || (beforeBalance >= afterFirst && beforeBalance - afterFirst >= depositAmount && (secondReverted || afterSecond == afterFirst)));
    }

    receive() external payable { }
}

